// app.js — LivLens frontend. Loads areas.geojson (generated by scripts/build.py)
// and renders it on a Leaflet map.
//
// Two things are fully schema-agnostic — they read whatever columns exist in
// data/areas.csv without any code change here:
//   1. The side panel — renders every populated property on the clicked area.
//   2. The filters panel — auto-detects filterable columns (numeric or a
//      short list of repeated values) and builds a filter control for each.
//
// Filter model: every filter is marked "strict" or "negotiable". An area's
// computed colour is:
//   red    — fails at least one active STRICT filter (a dealbreaker)
//   yellow — passes all strict filters but fails an active negotiable one
//   green  — passes every active filter
// If no filters are active, the manual `status` column from the CSV is used
// instead, so the map still works with zero filters touched.

const STATUS_COLORS = {
  green: "#34d399",
  yellow: "#fbbf24",
  red: "#f87171",
};

const HIDDEN_FIELDS = new Set(["lat", "lon", "radius_m"]);
const NON_FILTERABLE_FIELDS = new Set([
  "name", "city", "country", "status", "lat", "lon", "radius_m", "notes",
]);
const MAX_CATEGORICAL_OPTIONS = 8;

// zoomControl: false + added back top-right so it doesn't collide with the
// filters panel, which slides in from the top-left.
const map = L.map("map", { zoomControl: false }).setView([6.24, -75.58], 12);
L.control.zoom({ position: "topright" }).addTo(map);

L.tileLayer(
  "https://{s}.basemaps.cartocdn.com/rastertiles/dark_all/{z}/{x}/{y}{r}.png",
  {
    attribution:
      '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
    maxZoom: 19,
  }
).addTo(map);

const panel = document.getElementById("panel");
const panelContent = document.getElementById("panel-content");
const panelClose = document.getElementById("panel-close");
const emptyHint = document.getElementById("empty-hint");
const filtersPanel = document.getElementById("filters-panel");
const filtersContent = document.getElementById("filters-content");
const filtersToggle = document.getElementById("filters-toggle");
const filtersReset = document.getElementById("filters-reset");

const activeStatuses = new Set(["green", "yellow", "red"]);
let geoLayer = null;
let filterDefs = [];
let filterState = {};

function prettifyLabel(key) {
  return key
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .replace(/\bUsd\b/i, "USD")
    .replace(/\bM\b/, "m");
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

// ---------------------------------------------------------------------------
// Filter engine
// ---------------------------------------------------------------------------

function buildFilterDefinitions(features) {
  const fieldValues = {};
  features.forEach((f) => {
    Object.entries(f.properties).forEach(([key, value]) => {
      if (NON_FILTERABLE_FIELDS.has(key)) return;
      if (value === undefined || value === null || value === "") return;
      (fieldValues[key] = fieldValues[key] || []).push(String(value));
    });
  });

  const defs = [];
  Object.entries(fieldValues).forEach(([key, values]) => {
    const isNumeric = values.every((v) => v !== "" && !isNaN(parseFloat(v)) && isFinite(v));
    if (isNumeric) {
      const nums = values.map(Number);
      const min = Math.min(...nums);
      const max = Math.max(...nums);
      if (min === max) return; // no variation to filter on
      defs.push({ key, type: "numeric", label: prettifyLabel(key), min, max });
    } else {
      const distinct = [...new Set(values)].sort();
      if (distinct.length > 1 && distinct.length <= MAX_CATEGORICAL_OPTIONS) {
        defs.push({ key, type: "categorical", label: prettifyLabel(key), options: distinct });
      }
    }
  });
  return defs.sort((a, b) => a.label.localeCompare(b.label));
}

function initFilterState(defs) {
  const state = {};
  defs.forEach((def) => {
    if (def.type === "numeric") {
      state[def.key] = { threshold: def.max, strict: false };
    } else {
      state[def.key] = { selected: new Set(def.options), strict: false };
    }
  });
  return state;
}

function isFilterActive(def) {
  const s = filterState[def.key];
  if (def.type === "numeric") return s.threshold < def.max;
  return s.selected.size < def.options.length;
}

function evaluateFilter(def, rawValue) {
  if (rawValue === undefined || rawValue === null || rawValue === "") return true; // unknown data doesn't disqualify
  const s = filterState[def.key];
  if (def.type === "numeric") return parseFloat(rawValue) <= s.threshold;
  return s.selected.has(String(rawValue));
}

function computeColor(feature) {
  const manualColor = STATUS_COLORS[(feature.properties.status || "").toLowerCase()] || "#64748b";
  const activeDefs = filterDefs.filter(isFilterActive);
  if (activeDefs.length === 0) return manualColor;

  let dealbreaker = false;
  let softFail = false;
  for (const def of activeDefs) {
    const pass = evaluateFilter(def, feature.properties[def.key]);
    if (!pass) {
      if (filterState[def.key].strict) dealbreaker = true;
      else softFail = true;
    }
  }
  if (dealbreaker) return STATUS_COLORS.red;
  if (softFail) return STATUS_COLORS.yellow;
  return STATUS_COLORS.green;
}

function colorToStatusName(color) {
  return Object.keys(STATUS_COLORS).find((k) => STATUS_COLORS[k] === color) || null;
}

function renderFiltersPanel() {
  if (filterDefs.length === 0) {
    filtersContent.innerHTML = `<p class="filters-empty">No filterable columns found in areas.csv.</p>`;
    return;
  }

  filtersContent.innerHTML = filterDefs
    .map((def) => {
      const s = filterState[def.key];
      const active = isFilterActive(def);
      let controlHtml;
      if (def.type === "numeric") {
        controlHtml = `
          <input type="range" min="${def.min}" max="${def.max}" value="${s.threshold}" data-key="${def.key}" class="filter-range" />
          <div class="filter-range-value">\u2264 ${s.threshold}</div>`;
      } else {
        controlHtml = def.options
          .map(
            (opt) => `
          <label class="filter-option">
            <input type="checkbox" data-key="${def.key}" data-option="${escapeHtml(opt)}" ${s.selected.has(opt) ? "checked" : ""} />
            ${escapeHtml(opt)}
          </label>`
          )
          .join("");
      }
      return `
        <div class="filter-row ${active ? "active" : ""}">
          <div class="filter-row-header">
            <span class="filter-label">${escapeHtml(def.label)}</span>
            <label class="strict-toggle" title="Strict = a dealbreaker (colours the area red). Negotiable = a soft mismatch (colours it yellow).">
              <input type="checkbox" data-strict-key="${def.key}" ${s.strict ? "checked" : ""} />
              Strict
            </label>
          </div>
          <div class="filter-control">${controlHtml}</div>
        </div>`;
    })
    .join("");

  filtersContent.querySelectorAll(".filter-range").forEach((el) => {
    el.addEventListener("input", () => {
      filterState[el.dataset.key].threshold = Number(el.value);
      renderFiltersPanel();
      applyStyles();
    });
  });
  filtersContent.querySelectorAll('input[type="checkbox"][data-key]').forEach((el) => {
    el.addEventListener("change", () => {
      const { key, option } = el.dataset;
      const selected = filterState[key].selected;
      if (el.checked) selected.add(option);
      else selected.delete(option);
      renderFiltersPanel();
      applyStyles();
    });
  });
  filtersContent.querySelectorAll("input[data-strict-key]").forEach((el) => {
    el.addEventListener("change", () => {
      filterState[el.dataset.strictKey].strict = el.checked;
      applyStyles();
    });
  });
}

function resetFilters() {
  filterState = initFilterState(filterDefs);
  renderFiltersPanel();
  applyStyles();
}

filtersToggle.addEventListener("click", () => {
  filtersPanel.classList.toggle("open");
});
filtersReset.addEventListener("click", resetFilters);

// ---------------------------------------------------------------------------
// Map styling + side panel
// ---------------------------------------------------------------------------

function styleFeature(feature) {
  return {
    fillColor: computeColor(feature),
    fillOpacity: 0.55,
    color: "rgba(226, 232, 240, 0.55)",
    weight: 1.5,
  };
}

function applyStyles() {
  if (!geoLayer) return;
  geoLayer.eachLayer((layer) => {
    const color = computeColor(layer.feature);
    const statusName = colorToStatusName(color);
    const visible = !statusName || activeStatuses.has(statusName);
    layer.setStyle({
      fillColor: color,
      fillOpacity: visible ? 0.55 : 0,
      opacity: visible ? 1 : 0,
      weight: 1.5,
    });
    layer.options.interactive = visible;
  });
}

function renderPanel(properties) {
  const status = (properties.status || "").toLowerCase();
  const name = properties.name || "Unnamed area";
  const city = properties.city || "";
  const country = properties.country || "";

  let html = `<h2>${escapeHtml(name)}</h2>`;
  html += `<div class="subtitle">${escapeHtml([city, country].filter(Boolean).join(", "))}</div>`;
  if (status) {
    html += `<div class="status-badge ${status}">${escapeHtml(status)}</div>`;
  }

  for (const [key, value] of Object.entries(properties)) {
    if (HIDDEN_FIELDS.has(key)) continue;
    if (["name", "city", "country", "status"].includes(key)) continue;
    if (value === undefined || value === null || value === "") continue;
    html += `<div class="field"><div class="label">${escapeHtml(prettifyLabel(key))}</div><div class="value">${escapeHtml(String(value))}</div></div>`;
  }

  panelContent.innerHTML = html;
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

function openPanel(properties) {
  renderPanel(properties);
  panel.classList.add("open");
  emptyHint.style.display = "none";
  const slug = (properties.name || "").toLowerCase().replace(/\s+/g, "-");
  if (slug) history.replaceState(null, "", `#${slug}`);
}

function closePanel() {
  panel.classList.remove("open");
  history.replaceState(null, "", location.pathname);
}

panelClose.addEventListener("click", closePanel);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") closePanel();
});

document.querySelectorAll(".filter-chip").forEach((chip) => {
  chip.addEventListener("click", () => {
    const status = chip.dataset.status;
    if (activeStatuses.has(status)) {
      activeStatuses.delete(status);
      chip.classList.add("off");
    } else {
      activeStatuses.add(status);
      chip.classList.remove("off");
    }
    applyStyles();
  });
});

fetch("areas.geojson")
  .then((res) => res.json())
  .then((data) => {
    if (!data.features || data.features.length === 0) {
      emptyHint.textContent = "No areas yet — add a row to data/areas.csv";
      emptyHint.style.display = "block";
      return;
    }

    filterDefs = buildFilterDefinitions(data.features);
    filterState = initFilterState(filterDefs);
    renderFiltersPanel();

    geoLayer = L.geoJSON(data, {
      style: styleFeature,
      onEachFeature: (feature, layer) => {
        layer.on("mouseover", () => layer.setStyle({ weight: 3 }));
        layer.on("mouseout", () => layer.setStyle({ weight: 1.5 }));
        layer.on("click", () => {
          const statusName = colorToStatusName(computeColor(feature));
          if (!statusName || activeStatuses.has(statusName)) openPanel(feature.properties);
        });
      },
    }).addTo(map);

    map.fitBounds(geoLayer.getBounds(), { padding: [20, 20] });
    emptyHint.style.display = "block";

    // Deep-link support: #laureles opens that area's panel on load.
    const slug = location.hash.replace("#", "");
    if (slug) {
      const match = data.features.find(
        (f) => (f.properties.name || "").toLowerCase().replace(/\s+/g, "-") === slug
      );
      if (match) openPanel(match.properties);
    }
  })
  .catch((err) => {
    emptyHint.textContent = "Could not load areas.geojson — run scripts/build.py";
    emptyHint.style.display = "block";
    console.error(err);
  });
